// === 전날(KST) 기준으로 Google Sheets 주문을 모아서 매출 계산 ===
// - 사용 컬럼: 타임스탬프, 주문 상품명, 주문 수량
// - 단가: 상품A = 10,000원, 상품B = 20,000원

const { DateTime } = globalThis;

// 0. 기준시간 (KST)과 전날 범위 계산
const KST = 'Asia/Seoul';
const nowKst = $now.setZone(KST);
const yStart = nowKst.minus({ days: 1 }).startOf('day'); // 전날 00:00:00
const yEnd   = nowKst.minus({ days: 1 }).endOf('day');   // 전날 23:59:59.999

// 0-1. 가격 테이블 (상품명 → 단가)
const PRICE_TABLE = {
  '상품A': 10000,
  '상품B': 20000,
};

// 1. 필드 이름들
const DATE_KEYS    = ['타임스탬프', '타임 스탬프'];
const PRODUCT_KEYS = ['주문 상품명', '상품명', '주문 상품'];
const QTY_KEYS     = ['주문 수량', '수량', 'quantity', 'qty'];

function pick(obj, keys) {
  for (const k of keys) {
    if (obj?.[k] !== undefined && obj[k] !== null && obj[k] !== '') return obj[k];
  }
  return undefined;
}

// "2025. 11. 12 오후 6:58:46" 같은 한국어 포맷 전용 파서
function parseKoreanTimestamp(v) {
  if (!v) return null;
  let s = (typeof v === 'string') ? v : (v?.text ?? v?.value ?? v?.name ?? String(v));
  s = s.replace(/\u00a0/g, ' ').trim();

  const m = s.match(/^(\d{4})\.\s*(\d{1,2})\.\s*(\d{1,2})\s+(오전|오후)\s+(\d{1,2}):(\d{2}):(\d{2})$/);
  if (!m) return null;

  let [, year, month, day, ampm, hour, minute, second] = m;
  year = Number(year); month = Number(month); day = Number(day);
  hour = Number(hour); minute = Number(minute); second = Number(second);

  if (ampm === '오전') {
    if (hour === 12) hour = 0;
  } else if (ampm === '오후') {
    if (hour !== 12) hour += 12;
  }

  return DateTime.fromObject({ year, month, day, hour, minute, second }, { zone: KST });
}

function parseAnyTimestamp(v) {
  if (!v) return null;
  const tk = parseKoreanTimestamp(v);
  if (tk) return tk;

  const s = (typeof v === 'string') ? v : (v?.text ?? v?.value ?? v?.name ?? String(v));
  if (!s) return null;

  const isoTry = DateTime.fromISO(s.trim(), { zone: KST });
  if (isoTry.isValid) return isoTry;
  return null;
}

function toNumber(v) {
  const raw = (typeof v === 'object') ? (v?.value ?? v?.text ?? v?.name ?? 0) : v;
  const n = Number(String(raw).replace(/[, ]/g, ''));
  return Number.isFinite(n) ? n : 0;
}

function fmt(n) {
  try {
    return new Intl.NumberFormat('ko-KR').format(Math.round(n));
  } catch { return String(n); }
}

// 2. 시트 데이터 읽기
const items = $input.all();

let total = 0;
let totalQty = 0;
const breakdown = [];

for (const item of items) {
  const row = item.json;

  const dateValue = pick(row, DATE_KEYS);
  const ts = parseAnyTimestamp(dateValue);
  if (!ts) continue;
  if (ts < yStart || ts > yEnd) continue; // 전날만

  const product = String(pick(row, PRODUCT_KEYS) ?? '');
  const qty     = toNumber(pick(row, QTY_KEYS));

  const unitPrice = PRICE_TABLE[product] ?? 0;
  const lineTotal = qty * unitPrice;

  totalQty += qty;
  total    += lineTotal;

  breakdown.push({
    상품: product,
    수량: qty,
    단가: unitPrice,
    총액: lineTotal,
  });
}

const ymd = yStart.toFormat('yyyy-LL-dd');

const lines = breakdown.map((b, i) =>
  `${i + 1}. ${b.상품 || '(상품명)'} x${b.수량 || '?'} = ${fmt(b.총액)}원`,
);

const subject =
  `[일일 매출 보고] ${ymd} (전날 주문 ${breakdown.length}건 / 총 수량 ${fmt(totalQty)}개 / 매출 ${fmt(total)}원)`;

const body = [
  `기준일: ${ymd} (KST, 전날 주문 기준)`,
  `전날 주문 건수: ${breakdown.length}건`,
  `전날 총 수량: ${fmt(totalQty)}개`,
  `전날 매출 합계: ${fmt(total)}원`,
  '',
  '— 상세 내역 —',
  ...(lines.length ? lines : ['(해당 일 주문 없음)']),
].join('\n');

return [
  {
    json: {
      to: 'iuandn63@gmail.com',
      subject,
      text: body,
      total,
      totalQty,
      count: breakdown.length,
      debug: {
        nowKst: nowKst.toISO(),
        yStart: yStart.toISO(),
        yEnd: yEnd.toISO()
      }
    }
  }
];
